count = 0
for each row:
    for each col:
        if grid[row][col] == 1:
            count += 1
            stack = [(row, col)]
            while stack is not empty:
                r, c = pop(stack)
                if r, c is outside the grid or grid[r][c] != 1:
                    continue
                grid[r][c] = 0
                push (r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)
return count
